                ["es-ES"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Activar Stop Jaywalking", ["opt.Enabled.D"]="Hace que cruzar imprudentemente (cruzar una calle lejos de un paso de peatones marcado) sea costoso, de modo que los peatones se canalicen hacia los pasos de cebra. Desactivado = comportamiento vanilla.", ["opt.CostMultiplier.L"]="Multiplicador de coste del cruce imprudente", ["opt.CostMultiplier.D"]="Cuánto más costoso es un cruce sin marcar frente al vanilla. Cuanto mayor, más evitan los peatones cruzar imprudentemente y se desvían a los pasos marcados. Nadie queda nunca totalmente atrapado: si no hay ningún cruce accesible, cruzan igualmente, aunque a regañadientes.", ["opt.ReassertIntervalHours.L"]="Intervalo de reaplicación (horas del juego)", ["opt.ReassertIntervalHours.D"]="Con qué frecuencia el mod vuelve a aplicar el coste. El juego puede restablecerlo tras grandes cambios de carreteras; un intervalo más corto lo reaplica antes.", ["grp.Group"]="Pasos de peatones", ["grp.GroupGeneral"]="General", },
