                ["it-IT"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Abilita Stop Jaywalking", ["opt.Enabled.D"]="Rende l'attraversamento irregolare (attraversare una strada lontano da un attraversamento pedonale segnalato) costoso, così i pedoni si incanalano verso le strisce pedonali. Disattivato = comportamento originale.", ["opt.CostMultiplier.L"]="Moltiplicatore di costo dell'attraversamento irregolare", ["opt.CostMultiplier.D"]="Quanto è più costoso un attraversamento non segnalato rispetto all'originale. Più alto = i pedoni evitano di più l'attraversamento irregolare e deviano verso quelli segnalati. Nessuno resta mai del tutto bloccato — se nessun attraversamento è raggiungibile attraversano comunque, ma con riluttanza.", ["opt.ReassertIntervalHours.L"]="Intervallo di riapplicazione (ore di gioco)", ["opt.ReassertIntervalHours.D"]="Ogni quanto la mod riapplica il costo. Il gioco può azzerarlo dopo ampie modifiche stradali; un intervallo più breve lo riapplica prima.", ["grp.Group"]="Attraversamenti pedonali", ["grp.GroupGeneral"]="Generale", },
                ["ja-JP"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Stop Jaywalking を有効化", ["opt.Enabled.D"]="無断横断（横断歩道のない場所での道路横断）のコストを高くし、歩行者を横断歩道へ誘導します。オフ = バニラの挙動。", ["opt.CostMultiplier.L"]="無断横断コスト倍率", ["opt.CostMultiplier.D"]="横断歩道のない横断が、バニラと比べてどれだけコスト高になるか。高いほど歩行者は無断横断を強く避け、横断歩道へ迂回します。完全に立ち往生することはありません。横断できる場所がない場合は、しぶしぶながらも横断します。", ["opt.ReassertIntervalHours.L"]="再適用間隔（ゲーム内時間）", ["opt.ReassertIntervalHours.D"]="Modがコストを再適用する頻度。大規模な道路編集の後にゲームがリセットすることがあり、間隔を短くするとより早く再適用されます。", ["grp.Group"]="歩行者の横断", ["grp.GroupGeneral"]="全般", },
