                ["pl-PL"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Włącz Stop Jaywalking", ["opt.Enabled.D"]="Sprawia, że przechodzenie przez jezdnię w miejscu niedozwolonym (z dala od wyznaczonego przejścia) staje się kosztowne, dzięki czemu piesi kierują się na przejścia dla pieszych. Wyłączone = zachowanie z gry podstawowej.", ["opt.CostMultiplier.L"]="Mnożnik kosztu przechodzenia w miejscu niedozwolonym", ["opt.CostMultiplier.D"]="O ile bardziej kosztowne jest przejście w miejscu niewyznaczonym w porównaniu z grą podstawową. Wyższa wartość = piesi mocniej unikają przechodzenia w miejscu niedozwolonym i nadkładają drogi do wyznaczonych przejść. Nikt nigdy nie zostaje całkowicie uwięziony — jeśli żadne przejście nie jest osiągalne, piesi i tak przejdą, tylko niechętnie.", ["opt.ReassertIntervalHours.L"]="Odstęp ponownego zastosowania (godziny w grze)", ["opt.ReassertIntervalHours.D"]="Jak często mod ponownie stosuje koszt. Gra może go zresetować po dużych zmianach dróg; krótszy odstęp przywraca go szybciej.", ["grp.Group"]="Przejścia dla pieszych", ["grp.GroupGeneral"]="Ogólne", },
                ["pt-BR"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Ativar Stop Jaywalking", ["opt.Enabled.D"]="Torna a travessia irregular (atravessar a rua longe de uma faixa demarcada) cara, para que os pedestres se concentrem nas faixas de pedestres. Desativado = comportamento original.", ["opt.CostMultiplier.L"]="Multiplicador de custo da travessia irregular", ["opt.CostMultiplier.D"]="Quanto mais custosa é uma travessia sem faixa em relação ao original. Quanto maior, mais os pedestres evitam a travessia irregular e desviam para faixas demarcadas. Ninguém fica totalmente preso — se nenhuma faixa for alcançável, eles ainda atravessam, só que a contragosto.", ["opt.ReassertIntervalHours.L"]="Intervalo de reaplicação (horas do jogo)", ["opt.ReassertIntervalHours.D"]="Com que frequência o mod reaplica o custo. O jogo pode redefini-lo após grandes edições de vias; um intervalo mais curto reaplica mais cedo.", ["grp.Group"]="Faixas de pedestres", ["grp.GroupGeneral"]="Geral", },
                ["ru-RU"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Включить Stop Jaywalking", ["opt.Enabled.D"]="Делает переход в неположенном месте (переход дороги вне обозначенного перехода) дорогим, чтобы пешеходы направлялись к пешеходным переходам. Выкл = поведение оригинала.", ["opt.CostMultiplier.L"]="Множитель стоимости перехода в неположенном месте", ["opt.CostMultiplier.D"]="Насколько дороже переход в неположенном месте по сравнению с оригиналом. Выше = пешеходы сильнее избегают перехода в неположенном месте и обходят к обозначенным переходам. Никто никогда полностью не застревает — если ни один переход недостижим, они всё равно перейдут, просто неохотно.", ["opt.ReassertIntervalHours.L"]="Интервал повторного применения (игровые часы)", ["opt.ReassertIntervalHours.D"]="Как часто мод заново применяет стоимость. Игра может сбросить её после крупных правок дорог; более короткий интервал применяет её быстрее.", ["grp.Group"]="Пешеходные переходы", ["grp.GroupGeneral"]="Общие", },
                ["zh-HANS"] = new Dictionary<string, string> { ["opt.Enabled.L"]="启用禁止乱穿马路", ["opt.Enabled.D"]="使乱穿马路（在远离标记人行横道处横穿道路）代价高昂，从而引导行人集中到斑马线通行。关闭 = 原版行为。", ["opt.CostMultiplier.L"]="乱穿马路代价倍率", ["opt.CostMultiplier.D"]="无标记横穿相较原版要高出多少代价。数值越高，行人越强烈地避免乱穿并绕行至标记人行横道。任何人都不会被彻底困住——若无横道可达，他们仍会横穿，只是很不情愿。", ["opt.ReassertIntervalHours.L"]="重新施加间隔（游戏内小时）", ["opt.ReassertIntervalHours.D"]="模组重新施加代价的频率。大规模道路编辑后游戏可能将其重置；间隔越短，重新施加越快。", ["grp.Group"]="人行横道", ["grp.GroupGeneral"]="常规", },
